// Counts what is asked of the disk and lets every asking through, under the names that node:fs has for it.
var fs = require("fs"), heard = {};
["existsSync", "statSync", "readdirSync"].forEach(function (name) {
  var below = fs[name];
  fs[name] = function () { heard[name] = (heard[name] || 0) + 1; return below.apply(this, arguments); };
});
exports.ok = [fs.existsSync("."), require("node:fs").statSync(".").isDirectory(), Array.isArray(fs.readdirSync(".")), Object.keys(heard).join("+")].join();
